def solve_dp():
    target = 2015
    for N in range(1, 10000):
        # dp[i][c] = max_size of S subset {1, ..., i}
        # where c is the number of consecutive elements ending at i.
        # We also need to handle the {1, 2} and {N-1, N} conditions.

        # Since we only need the max size, and the {1, 2} and {N-1, N} conditions 
        # only depend on the start and end, let's just run the DP.

        # dp[i][c] = set of all possible first_used values
        # This is also not quite right. Let's just keep track of the max size for each (c, f).

        # dp[i][c][f] = max size of S subset {1, ..., i}
        # c = number of consecutive elements ending at i (0, 1, 2)
        # f = 1 if 1 is in S, 0 otherwise

        dp = [[[-1] * 2 for _ in range(3)] for _ in range(N + 1)]

        # Base case i = 1:
        dp[1][0][0] = 0
        dp[1][1][1] = 1

        for i in range(2, N + 1):
            for c in range(3):
                for f in range(2):
                    if dp[i-1][c][f] == -1: continue
                    size = dp[i-1][c][f]

                    # Option 1: Don't include i
                    dp[i][0][f] = max(dp[i][0][f], size)

                    # Option 2: Include i
                    if c < 2:
                        # Condition: no {1, 2}
                        if not (i == 2 and f == 1):
                            dp[i][c+1][1 if i == 1 else f] = max(dp[i][c+1][1 if i == 1 else f], size + 1)

        max_s = 0
        for c in range(3):
            for f in range(2):
                if dp[N][c][f] != -1:
                    # Condition: no {N-1, N}
                    if c < 2:
                        max_s = max(max_s, dp[N][c][f])

        if max_s >= target:
            return

